from decimal import Decimal

from .money import MAX_CENTS, format_amount, parse_amount, to_cents


def make_invoice(amounts):
    items = list(amounts)  # copy; the caller's input is never mutated
    total_cents = 0
    for item in items:
        total_cents += to_cents(parse_amount(item))
    if total_cents > MAX_CENTS:
        raise ValueError("total must be at most 1000000.00")
    total = Decimal(f"{total_cents // 100}.{total_cents % 100:02d}")
    return {"total": format_amount(total), "count": len(items)}

