import re
from decimal import Decimal

MAX_AMOUNT = Decimal("1000000.00")
MAX_CENTS = 100_000_000

# Plain decimal: optional sign, digits, optional fraction. No whitespace, no exponent.
_PLAIN_DECIMAL = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def parse_amount(value):
    """Parse a money amount into a positive Decimal with exponent -2.

    Accepts Decimal, int (not bool) and plain decimal strings. Anything else,
    non-finite values, zero, negatives, values above MAX_AMOUNT and values that
    are not exactly representable in cents raise ValueError. Nothing is rounded.
    """
    if isinstance(value, bool):
        raise ValueError("boolean is not an amount")
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, int):
        amount = Decimal(value)
    elif isinstance(value, str):
        if _PLAIN_DECIMAL.fullmatch(value) is None:
            raise ValueError(f"not a plain decimal string: {value!r}")
        amount = Decimal(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    # is_finite() must come first: comparisons with NaN/sNaN raise or are undefined.
    if not amount.is_finite():
        raise ValueError("amount must be finite")
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > MAX_AMOUNT:
        raise ValueError("amount must be at most 1000000.00")

    # Exact-cents check on the digit tuple: no context, no rounding.
    _, digits, exponent = amount.as_tuple()
    digits = list(digits)
    while exponent < -2 and digits[-1] == 0:
        digits.pop()
        exponent += 1
    if exponent < -2:
        raise ValueError("amount is not exactly representable in cents")
    digits.extend([0] * (exponent + 2))
    return Decimal((0, tuple(digits), -2))


def to_cents(amount):
    """Return the integer number of cents in a Decimal with exponent -2 (exact, context-free)."""
    return int("".join(str(d) for d in amount.as_tuple().digits))


def format_amount(value):
    return format(value, ".2f")
